-- Sample graphs of the terrain graph editor (shipped data: one .lua file per graph in this folder).
List = {
    { id = 'mountains', name = 'Mountains (ridges, droplet erosion, cliffs and snow)', note = 'Ridged noise bent by a warp, scaled to heights, eroded by droplets; cliffs on the steep ground, snow on the high ground.' },
    { id = 'island', name = 'Island (radial falloff, hills, beach)', note = 'A noisy island: noise times a radial falloff, droplet erosion (valleys running down to the coast), a sand beach on the shore band.' },
    { id = 'canyon', name = 'Canyon (stream power river gorges)', note = 'A plateau cut by a drainage network of deep river valleys; rock on the walls.' },
    { id = 'hills', name = 'Rolling hills (two noises, hydraulic erosion)', note = 'Soft hills from simplex and billow noise blended together, then eroded by water. Dirt patches on the flat ground.' },
    { id = 'desert', name = 'Desert (mesas, dunes, sand)', note = 'Terraced mesas cut by dry washes and fans (sparse droplet erosion); sand on the flat ground, rock on the steep.' },
    { id = 'river_valley', name = 'River valley (a river path through hills)', note = 'Gentle hills with a river carved along a wobbling path: a flat bed under the water level, banks, sand along the river.' },
    { id = 'symmetric', name = 'Symmetric hills (four-fold mirror)', note = 'Hills mirrored across both axes, exact copies: a fair, symmetric map by construction. Change the mode to rotate for a two-player map.' },
    { id = 'archipelago', name = 'Archipelago (many islands)', note = 'Cell noise cut into islands, rough coasts from fine noise, sand on the shores.' },
    { id = 'crater', name = 'Crater lake (rim and bowl)', note = 'A radial profile drawn as a curve: bowl, high rim, outer slope; noise breaks it up. The bowl fills with the map\'s water.' },
    { id = 'badlands', name = 'Badlands (terraced ridges and gullies)', note = 'Sharp ridged terrain stepped into layers, slumped by thermal erosion, cut by river gullies.' },
    { id = 'plains', name = 'Plains with a ridge line (path raise)', note = 'Nearly flat country with a low ridge raised along a path, forest density from noise (add props to the scatter node).' },
    { id = 'valley', name = 'Open valley (plains, hills and cliffs)', note = 'The layout of a good map: flat open plains with clusters of hills that have defined flanks (Landforms node), droplet erosion for realism, painted with the open valley style: bare plains, green hills, rock on the steep ground.' },
    { id = 'layout_terrain', name = 'Layout to terrain (drawn layout, terraces, noise on the slopes, erosion)', note = 'The way a hand made map is built: the layout you drew in the Layout workspace, blurred and terraced, a ridged noise that only lives on the slopes, droplet erosion, a blur, a second erosion for the whole ground, the paint from the erosion masks. Draw (or choose a template in) the Layout workspace first.' },
    { id = 'external_terrain', name = 'Gaea / World Machine terrain (heights, erosion masks, ground kinds)', note = 'Starts from the heightmap of the Interop panel (Gaea, World Machine, Blender ...): the terrain as it is, the ground kinds painted from it, and the flow / wear / deposit masks you imported (Masks page, named masks; files called Flow, Wear, Deposits are recognised) decide where the dirt, rock and wet ground go. The graph follows the files: it evaluates again when the other tool writes a new one.' },
    { id = 'eroded_hills', name = 'Eroded hills painted by the water (hydraulic wear, deposit and flow masks)', note = 'Hills carved by hydraulic erosion; its own wear, deposit and flow masks decide rock, sediment and the drainage channels, the second texture of a kind is a band of those masks. Crisp edges, no noise patches. Use the Layered textures button first for several textures per kind.' },
    { id = 'external_erosion', name = 'Gaea / World Machine terrain, painted by the erosion masks', note = 'The imported terrain painted the way a World Machine or Gaea project does: worn rock, sediment and drainage channels from the wear, deposit and flow masks (made from the heights when you imported none), the second texture of a kind as a band of those masks. Crisp edges, no noise patches.' },
    { id = 'texturing', name = 'Texture the existing terrain (ground kinds for any shader)', note = 'Reads the heights of the map and paints all kinds of ground (grass, dirt, wet ground, sand, rock, dark rock, high rock, snow) with the stratum recipe for the shader of the map: 4, 7 or 8 layers, the base layer, side-mapped layers, terrain types and roughness. The Terrain shader node shows what the shader paints.' },
    { id = 'pathable', name = 'Gentle hills made pathable (slope check)', note = 'Hills whose steep parts are smoothed away, plus a view of the ground land units cannot cross (Mask view on the last node).' },
    { id = 'two_players', name = 'Two player map (symmetric, flat bases, pathable)', note = 'Hills with a base pad, turned by 180 degrees so both bases and all terrain are exact copies, then the slope limited to what units can cross. For a real map set the pad node to markers mode (pads under the start positions and resource markers).' },
    { id = 'pathing', name = 'Pathing check (slope limit, passable regions)', note = 'Rough hills made pathable by the slope limit; the passable ground is labelled into connected regions and measured (select the Regions node and press Mask view or look at its numbers).' },
    { id = 'lib_duel_turn', name = 'Duel: two bases, turned 180 degrees', note = 'Competitive 1v1 base: hybrid multifractal hills made symmetric by a 180 degree turn (the average of the two images: continuous, exactly symmetric), a flat base pad on each side, the slope limited to what land units cross, textured by slope and wetness. Check: the blocked ground view.', library = true },
    { id = 'lib_duel_river', name = 'Duel: a river down the middle', note = 'Mirrored 1v1 map: rolling hills with a river on the symmetry axis, bases on both sides (one pad, mirrored), sand along the water, slope limited so every bank is passable.', library = true },
    { id = 'lib_ffa4_corners', name = 'Four players: corners, a central plateau', note = 'Four-fold turn (the average of the four images: exactly symmetric and continuous), a base pad in each corner, rolling terrain, a raised plateau in the middle every player can reach by a ramp, pathable slopes. Check: blocked ground.', library = true },
    { id = 'lib_ffa4_diag', name = 'Four players: mirrored ridges', note = 'Four-fold mirror (both axes): ridged mountains between the bases, a base pad per corner, slope limited so passes between ridges stay open. Rock layer from the rockiness mask.', library = true },
    { id = 'lib_hex6', name = 'Six players: a hexagon', note = 'Six-fold turn: the average of the six images (exactly symmetric when the map centre is on the sample lattice, continuous), a base pad for every player on a ring, slope limited. Change N in the Symmetrize node (and add pads) for 3, 4, 5 or 8 players.', library = true },
    { id = 'lib_two_islands', name = 'Two islands, a shallow channel', note = 'Naval 1v1: two ragged islands mirrored across the middle, hydraulic erosion, sand on the shore band, a pad for each base. Look at the map in the water view.', library = true },
    { id = 'lib_archipelago_fair', name = 'Archipelago, four-fold fair', note = 'Cell noise cut into islands (warped coast), a four-fold turn (larger of the four images) so each player gets the same islands, a base pad on each, hydraulic erosion, beach sand.', library = true },
    { id = 'lib_canyon_river', name = 'Canyon with a river', note = 'A terraced plateau cut by stream-power gorges and a river along a path: U-shaped canyon, rock layers (stratify) on the walls, sand on the river bed, a pad on each rim.', library = true },
    { id = 'lib_highlands', name = 'Highlands: massifs and valley floors', note = 'Mountain preset scaled to heights, sediment settles in the valley floors (flat building ground), rock layers on the steep faces, thermal talus, snow on the tops. The pad node flattens a base in a valley.', library = true },
    { id = 'lib_desert_dunes', name = 'Desert: dunes and mesas', note = 'Dune fields (asymmetric ridges with a meandering crest) between mesas, shaped by wind erosion, dry mud cracks on the flats; sand where the wind put it, rock on the faces.', library = true },
    { id = 'lib_tropics', name = 'Tropical island', note = 'A ragged island of soft hills, droplet erosion cuts the valleys, wetness makes the lush ground, a sand beach on the shore, dark undergrowth in the cavities. The base pad sits on the highest ground of its area.', library = true },
    { id = 'lib_alpine', name = 'Alpine: glaciers and snow', note = 'Ridged mountains, a glacier grinds U-shaped valleys above the equilibrium line, snow lies above the snow line and slumps off the steep faces, bare rock where it is steep or convex.', library = true },
    { id = 'lib_badlands', name = 'Badlands: layered rock', note = 'Stepped mesas, strongly layered cliffs (stratify), rock and soil split (soil slides into the hollows), dry cracks on the soil, cavity-darkened gullies.', library = true },
    { id = 'lib_moon', name = 'Moon: craters', note = 'Two sizes of impact craters on gentle terrain, settled and slope limited so the rims are climbable; cavity mask for the dark crater floors.', library = true },
    { id = 'lib_volcano', name = 'Volcano island', note = 'A cone with a crater (a drawn radial profile), warped and roughened by ridged noise, thermal slides, an ash apron; the coast is a ragged island shape.', library = true },
    { id = 'lib_tundra', name = 'Tundra: soft hills, snow and bogs', note = 'Low rolling hills, sediment settles into bogs (wetness), a thin snow cover that slumps off slopes, pathable throughout; two bases by a 180 degree turn (averaged images).', library = true },
    { id = 'lib_rift_valley', name = 'Rift valley between two plateaus', note = 'Two plateaus mirrored across a deep rift (a wide U canyon along a path), cracks and layered cliffs on the rift walls, ramps are left to the slope limit; sand on the rift floor.', library = true },
    { id = 'lib_mesa_fortress', name = 'Mesa fortress: bases on plateaus', note = 'Terraced mesas made symmetric by a 180 degree turn, a flat base pad on a plateau for each player, a ramp path down to the low ground, slope limited, regions measured: every base has to be one connected region.', library = true },
    { id = 'lib_wetlands', name = 'Wetlands: meanders and shallow lakes', note = 'Nearly flat country bent by a curl flow into meanders, sediment settles in the hollows (lakes where it dips under the water), wetness and the shore band texture the ground; fully pathable.', library = true },
    { id = 'lib_colour_pass', name = 'Texture, roughness and colour pass (no height change)', note = 'The ground kinds on the layers of the shader, plus what the shaders need besides the paint: the roughness mask (PBR), macrotexture, specular picture, roughness / height atlas (each is skipped with a note on a shader that does not read it) and a colour map file from the heights.', library = true },
}
